	if len(b) < 4 {
		return 0, false
	}
	var r rune
	for _, c := range b[:4] {
		r <<= 4
		switch {
		case '0' <= c && c <= '9':
			r |= rune(c - '0')
		case 'a' <= c && c <= 'f':
			r |= rune(c - 'a' + 10)
		case 'A' <= c && c <= 'F':
			r |= rune(c - 'A' + 10)
		default:
			return 0, false
		}
	}
	return r, true
}

// unescape decodes JSON string content into dst.
func unescape(dst, raw []byte) []byte {
	for i := 0; i < len(raw); {
		c := raw[i]
		if c != '\\' {
			j := i + 1
			for j < len(raw) && raw[j] != '\\' {
				j++
			}
			dst = append(dst, raw[i:j]...)
			i = j
			continue
		}
		if i+1 >= len(raw) {
			break
		}
		e := raw[i+1]
		i += 2
		switch e {
		case 'n':
			dst = append(dst, '\n')
		case 't':
			dst = append(dst, '\t')
		case 'r':
			dst = append(dst, '\r')
		case 'b':
			dst = append(dst, '\b')
		case 'f':
			dst = append(dst, '\f')
		case 'u':
			r, ok := hexVal(raw[i:])
			if !ok {
				dst = append(dst, "�"...)
				continue
			}
			i += 4
			if r >= 0xD800 && r < 0xDC00 {
				if i+6 <= len(raw) && raw[i] == '\\' && raw[i+1] == 'u' {
					if r2, ok := hexVal(raw[i+2:]); ok && r2 >= 0xDC00 && r2 < 0xE000 {
						i += 6
						r = 0x10000 + (r-0xD800)<<10 + (r2 - 0xDC00)
						dst = utf8.AppendRune(dst, r)
						continue
					}
				}
				r = 0xFFFD
			} else if r >= 0xDC00 && r < 0xE000 {
				r = 0xFFFD
			}
			dst = utf8.AppendRune(dst, r)
		default:
			dst = append(dst, e)
		}
	}
	return dst
}

func skipValue(b []byte, i int) (int, bool) {
	for i < len(b) && isWS(b[i]) {
		i++
	}
	if i >= len(b) {
		return 0, false
	}
	switch b[i] {
	case '"':
		_, n, _, ok := scanString(b, i)
		return n, ok
	case '{', '[':
		depth := 0
		for i < len(b) {
			switch b[i] {
			case '"':
				_, n, _, ok := scanString(b, i)
				if !ok {
					return 0, false
				}
				i = n
				continue
			case '{', '[':
				depth++
			case '}', ']':
				depth--
				if depth == 0 {
					return i + 1, true
				}
			}
			i++
		}
		return 0, false
	default:
		for i < len(b) && b[i] != ',' && b[i] != '}' && b[i] != ']' && !isWS(b[i]) {
			i++
		}
		return i, true
	}
}

type rawDoc struct {
	id         uint32
	title      []byte // raw JSON string content
	text       []byte
	titleEsc   bool
	textEsc    bool
}

func parseLine(b []byte) (d rawDoc, ok bool) {
	i := 0
	for i < len(b) && isWS(b[i]) {
		i++
	}
	if i >= len(b) || b[i] != '{' {
		return d, false
	}
	i++
	for {
		for i < len(b) && (isWS(b[i]) || b[i] == ',') {
			i++
		}
		if i >= len(b) {
			return d, false
		}
		if b[i] == '}' {
			return d, true
		}
		if b[i] != '"' {
			return d, false
		}
		key, n, _, ok := scanString(b, i)
		if !ok {
			return d, false
		}
		i = n
		for i < len(b) && isWS(b[i]) {
			i++
		}
		if i >= len(b) || b[i] != ':' {
			return d, false
		}
		i++
		for i < len(b) && isWS(b[i]) {
			i++
		}
		if i >= len(b) {
			return d, false
		}
		switch string(key) {
		case "id":
			var v uint64
			for i < len(b) && b[i] >= '0' && b[i] <= '9' {
				v = v*10 + uint64(b[i]-'0')
				i++
			}
			d.id = uint32(v)
		case "title", "text":
			if b[i] != '"' {
				return d, false
			}
			raw, n, esc, ok := scanString(b, i)
			if !ok {
				return d, false
			}
			i = n
			if key[1] == 'i' {
				d.title, d.titleEsc = raw, esc
			} else {
				d.text, d.textEsc = raw, esc
			}
		default:
			n, ok := skipValue(b, i)
			if !ok {
				return d, false
			}
			i = n
		}
	}
}

func isBlank(line []byte) bool {
	for _, c := range line {
		if !isWS(c) {
			return false
		}
	}
	return true
}

